using System.Globalization;
using StartPos.Core.Esf;
using StartPos.Core.Model;
using StartPos.Core.Tables;

namespace StartPos.Core.Decompile;

/// <summary>
/// Turns a built startpos.esf back into start_pos tables.
///
/// The game keeps some table IDs when it builds a startpos (faction, character and region IDs)
/// and drops others (settlement, unit, slot template, ... IDs); dropped ones are generated by
/// <see cref="IdAllocator"/>. Some columns are not in the startpos at all (see
/// <see cref="DecompileReport.Notes"/>) and get the value CA's data mostly uses.
/// </summary>
public sealed partial class StartPosDecompiler
{
    private readonly StartPosEsf _esf;
    private readonly GameLookups? _game;
    private readonly StartPosTables _tables = new();
    private readonly IdAllocator _ids = new();
    private readonly DecompileReport _report = new();

    private readonly Dictionary<long, FactionEntry> _factionsByCqi = [];
    private readonly Dictionary<string, FactionEntry> _factionsByKey = new(StringComparer.Ordinal);
    private readonly Dictionary<long, CharacterEntry> _charactersByMapCqi = [];
    private readonly List<CharacterEntry> _characters = [];
    private readonly Dictionary<long, RegionEntry> _regionsByCqi = [];
    private readonly List<RegionEntry> _regions = [];

    private StartPosDecompiler(StartPosEsf esf, GameLookups? game)
    {
        _esf = esf;
        _game = game;
    }

    public string Campaign => _esf.Campaign;

    /// <param name="game">
    /// The game's tables, used to leave out values that only repeat a default (a general's
    /// default unit, the only art set a subtype has). Without them those values are written out.
    /// </param>
    public static (StartPosTables Tables, DecompileReport Report) Decompile(StartPosEsf esf, GameLookups? game = null)
    {
        var d = new StartPosDecompiler(esf, game);
        d.Index();
        d.Run();
        return (d._tables, d._report);
    }

    private void Run()
    {
        _report.Notes.AddRange(
        [
            "start_pos_characters.loyalty, start_pos_regions.development_points and start_pos_settlements.startpos_slave_points are not kept in a built startpos; written as 0.",
            "Character names the game rejected (a name from another culture's names group, say) are empty in the startpos; Name/Surname are written empty.",
            "start_pos_diplomacy rows that only set 'neutral' with no treaties change nothing, so they are not in the startpos and are not written.",
            "start_pos_victory_conditions: the startpos keeps the regions, not the victory type; each region is written for both the long and the short victory.",
            "start_pos_past_events come from the campaign AI's interaction logs; events the build adds on turn 0 from the starting diplomacy are left out.",
        ]);
        ExtractFactions();
        ExtractCharacters();
        ExtractArmies();
        ExtractGeneralOptions();
        ExtractRegions();
        ExtractDiplomacy();
        ExtractTechnologies();
        ExtractVictoryConditions();
        ExtractCalendar();
        ExtractEntityAssociations();
        ExtractPastEvents();
        ExtractMercenarySets();
        ExtractAgentCultures();
        ExtractSubtypeNamesGroups();
    }

    // ------------------------------------------------------------- indexing

    /// <summary>Indexes factions, characters and regions, and reserves the IDs the startpos kept.</summary>
    private void Index()
    {
        var infos = new Dictionary<string, EsfRecord>(StringComparer.Ordinal);
        foreach (var info in _esf.FactionInfos)
            infos.TryAdd(info.Str(0), info);

        foreach (var faction in _esf.Factions)
        {
            long cqi = faction.Int(0);
            string key = faction.Str(1);
            var info = infos.GetValueOrDefault(key);
            // FACTION_INFOS #4 is the loc key "start_pos_factions_description_<ID>".
            string? id = info?.Str(4) is { } loc && loc.StartsWith(FactionDescriptionPrefix, StringComparison.Ordinal)
                ? loc[FactionDescriptionPrefix.Length..]
                : null;
            var entry = new FactionEntry(cqi, key, id ?? "", faction, info);
            _factionsByCqi[cqi] = entry;
            _factionsByKey[key] = entry;
            if (id != null && long.TryParse(id, out long n))
                _ids.Reserve(n);
        }
        foreach (var f in _factionsByCqi.Values.Where(f => f.Id.Length == 0).ToList())
        {
            var withId = f with { Id = _ids.For("faction|" + f.Key).ToString(CultureInfo.InvariantCulture) };
            _factionsByCqi[f.Cqi] = withId;
            _factionsByKey[f.Key] = withId;
            _report.Warn($"Faction {f.Key} has no start_pos ID in the startpos; generated {withId.Id}.");
        }

        // Characters on the map, by CQI, with the faction whose CHARACTER_ARRAY holds them.
        var onMap = new Dictionary<long, (EsfRecord Record, FactionEntry Faction)>();
        foreach (var f in _factionsByCqi.Values)
            foreach (var c in f.Faction.Record("CHARACTER_ARRAY")?.Elements() ?? [])
                onMap[c.Int(0)] = (c, f);

        // Every character the campaign knows is a FAMILY_MEMBER. Its CHARACTER_DETAILS #15 is the
        // start_pos_characters ID; characters the game made up itself (colonels, ...) have none.
        foreach (var member in _esf.FamilyMembers)
        {
            var details = member.Record("CHARACTER_DETAILS");
            if (details == null)
                continue;
            string id = details.Str(15);
            if (id.Length == 0)
                continue;
            long mapCqi = details.Int(2);
            var (mapRecord, mapFaction) = onMap.GetValueOrDefault(mapCqi);
            var faction = _factionsByKey.GetValueOrDefault(details.Str(1)) ?? mapFaction;
            var entry = new CharacterEntry(id, member, details, mapCqi, mapCqi != 0 ? mapRecord : null, faction);
            _characters.Add(entry);
            if (mapCqi != 0)
                _charactersByMapCqi[mapCqi] = entry;
            if (long.TryParse(id, out long n))
                _ids.Reserve(n);
        }

        foreach (var region in _esf.Regions)
        {
            long cqi = region.Int(0);
            string key = region.Str(1);
            var settlement = region.Required("SETTLEMENT");
            string settlementId = settlement.Str(2);
            // The settlement's on-screen name key is "start_pos_settlements_onscreen_name_" +
            // settlement_id + the start_pos_regions id.
            string loc = settlement.Record("CAMPAIGN_LOCALISATION")?.Str(0) ?? "";
            string prefix = SettlementNamePrefix + settlementId;
            long id = loc.StartsWith(prefix, StringComparison.Ordinal) && long.TryParse(loc[prefix.Length..], out long parsed) ? parsed : 0;
            if (id != 0)
                _ids.Reserve(id);
            var entry = new RegionEntry(cqi, key, id, region, settlement, settlementId);
            _regionsByCqi[cqi] = entry;
            _regions.Add(entry);
        }
        for (int i = 0; i < _regions.Count; i++)
        {
            if (_regions[i].Id != 0)
                continue;
            var withId = _regions[i] with { Id = _ids.For("region|" + _regions[i].Key) };
            _regions[i] = withId;
            _regionsByCqi[withId.Cqi] = withId;
            _report.Warn($"Region {withId.Key} has no start_pos ID in the startpos; generated {withId.Id}.");
        }
    }

    private const string FactionDescriptionPrefix = "start_pos_factions_description_";
    private const string SettlementNamePrefix = "start_pos_settlements_onscreen_name_";

    private string FactionId(long cqi) => _factionsByCqi.TryGetValue(cqi, out var f) ? f.Id : "";

    private DbTable Table(string name) => _tables[name];

    /// <summary>A generated ID for something the startpos does not keep the ID of.</summary>
    private string Id(string name) => _ids.For(name).ToString(CultureInfo.InvariantCulture);

    /// <summary>
    /// Runs <paramref name="action"/> for every item; an item whose records are not laid out
    /// as expected is reported and skipped instead of failing the whole decompile.
    /// </summary>
    private void Each<T>(IEnumerable<T> items, Func<T, string> describe, Action<T> action)
    {
        foreach (var item in items)
        {
            try
            {
                action(item);
            }
            catch (EsfFormatException ex)
            {
                _report.Warn($"{describe(item)}: {ex.Message} Skipped.");
            }
        }
    }

    private sealed record FactionEntry(long Cqi, string Key, string Id, EsfRecord Faction, EsfRecord? Info);

    private sealed record CharacterEntry(string Id, EsfRecord Member, EsfRecord Details, long MapCqi, EsfRecord? MapRecord, FactionEntry? Faction);

    private sealed record RegionEntry(long Cqi, string Key, long Id, EsfRecord Region, EsfRecord Settlement, string SettlementId);
}

/// <summary>What a decompile could not do exactly.</summary>
public sealed class DecompileReport
{
    public List<string> Warnings { get; } = [];

    /// <summary>Columns the startpos does not hold; written with a fixed value.</summary>
    public List<string> Notes { get; } = [];

    public void Warn(string message) => Warnings.Add(message);
}
